sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {

    const results = api.data.look_up_multiple_records_2.results || [];

    const unidadeSelecionada = api.state.select_unit;

    return results
        .filter(function(record) {
            return record.unidade &&
                   record.unidade.value === unidadeSelecionada;
        })
        .map(function(record) {
            return {
                id: record._row_data.uniqueValue,
                label: record.nome.displayValue || record.nome.value
            };
        });
}
